# Phrases qui portaient une dose non AIPS : on les retire du HTML généré.
MOTIFS = [
    "4,5 g",
    "15 mg/kg",
    "25 à 30 mg/kg",
    "toutes les 6 à 8",
    "1 g toutes les 8",
    "1 g toutes les 6",
    "1000 mg",
    "1 g par jour",
    "1 g une fois",
    "5 mg/kg",
    "2 g toutes les 6",
    "500 mg toutes les 6",
    "600 à 900",
    "600 mg toutes",
    "900 mg",
    "5 g toutes",
    "2 g/kg",
    "1 g/kg",
    "0,5 g/kg",
    "1 200 mg",
    "1 050 mg",
    "1 650 mg",
    "1050 mg",
    "1200 mg",
    "1650 mg",
    "350 mg",
    "550 mg",
    "18 g",
    "13,5 g",
    "2 g par jour",
]


def neutraliser(html: str) -> str:
    """Retire les paragraphes dont la dose n'est pas celle d'une notice Swissmedic."""
    import re

    def garder(m: re.Match) -> str:
        bloc = m.group(0)
        if "n° Swissmedic" in bloc:
            return bloc
        if any(motif in bloc for motif in MOTIFS):
            return ""
        return bloc

    return re.sub(r"<p\b[^>]*>.*?</p>", garder, html, flags=re.S)
